import{_ as e,o,c as r,a3 as i}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Início rápido","description":"","frontmatter":{"title":"Início rápido"},"headers":[],"relativePath":"inicio-rapido.md","filePath":"inicio-rapido.md"}'),s={name:"inicio-rapido.md"};function t(n,a,d,c,l,p){return o(),r("div",null,a[0]||(a[0]=[i('<h1 id="inicio-rapido" tabindex="-1">Início rápido <a class="header-anchor" href="#inicio-rapido" aria-label="Permalink to &quot;Início rápido&quot;">​</a></h1><p>Em poucos minutos: instalar, entender as permissões, ativar a extensão e, se quiser, ligar o backup no Google Drive.</p><h2 id="_1-instalar" tabindex="-1">1. Instalar <a class="header-anchor" href="#_1-instalar" aria-label="Permalink to &quot;1. Instalar&quot;">​</a></h2><p>O eploc é distribuído pela Chrome Web Store e funciona no <strong>Google Chrome</strong> e no <strong>Microsoft Edge</strong>.</p><ol><li>Abra a <a href="https://chromewebstore.google.com/detail/eploc/fkpkkenjcfpplmhlfdbabhcdhmhiojhj" target="_blank" rel="noreferrer">página do eploc na Chrome Web Store</a>.</li><li>Clique no botão de instalar da página. No Edge, se aparecer o aviso sobre extensões de outras lojas, permita-as e clique de novo no botão de instalar.</li><li>Confirme a instalação na janela de permissões do navegador.</li><li>Fixe o ícone do eploc na barra do navegador (ícone de quebra-cabeça → alfinete), para ter o <a href="./geral/popup">popup</a> sempre à mão.</li></ol><h2 id="_2-permissoes-solicitadas-e-para-que-servem" tabindex="-1">2. Permissões solicitadas e para que servem <a class="header-anchor" href="#_2-permissoes-solicitadas-e-para-que-servem" aria-label="Permalink to &quot;2. Permissões solicitadas e para que servem&quot;">​</a></h2><p>Ao instalar, o navegador mostra um resumo das permissões. O aviso mais chamativo costuma ser o de <strong>ler e alterar dados em sites</strong>: o eploc só atua nos endereços abaixo, e o navegador resume essa lista longa de endereços <code>jus.br</code> numa frase genérica, que pode reaparecer quando uma atualização inclui um novo tribunal.</p><table tabindex="0"><thead><tr><th>Permissão</th><th>Para que o eploc usa</th></tr></thead><tbody><tr><td>Acesso aos sites do eproc, SEI, RUPE e TJMG</td><td>Mostrar as melhorias nessas páginas. Endereços atendidos: eproc da JFRJ, JFES, TRF2, TRF4, JFRS, JFSC, JFPR, TRF6 (1º e 2º grau), TJRS, TJSC, TJTO, TJRJ, TJSP e TJMG (1º e 2º grau); <code>rupe.tjmg.jus.br</code>; o SEI em endereços <code>jus.br</code>; a consulta de dativos e o Meu Gabinete do TJMG (com o quadro de login <code>sso.cloud.pje.jus.br</code>). Veja <a href="./compatibilidade">Compatibilidade</a>.</td></tr><tr><td>Acesso a <code>midias.pje.jus.br</code></td><td>Conferir se há gravações de audiência para o <a href="./funcionalidades/eproc-midias-link">Atalho PJe Mídias</a>.</td></tr><tr><td>Armazenamento (<code>storage</code>)</td><td>Guardar suas configurações e dados (contatos, modelos, destaques etc.) no próprio navegador.</td></tr><tr><td>Leitura da área de transferência (<code>clipboardRead</code>)</td><td>O botão &quot;Preencher com dados copiados&quot; do <a href="./funcionalidades/rupe-cpha-preenchimento">Preenchimento automático de CPHA</a>.</td></tr><tr><td>Aba ativa (<code>activeTab</code>)</td><td>O popup saber em que página você está, para listar as funcionalidades que valem nela.</td></tr><tr><td>Identidade (<code>identity</code>)</td><td>Conectar sua conta Google ao <a href="./geral/backup-google-drive">backup no Google Drive</a>, só se você ligar esse recurso.</td></tr><tr><td>Alarmes (<code>alarms</code>)</td><td>Agendar a sincronização com o Google Drive.</td></tr><tr><td>Scripts e documento auxiliar (<code>scripting</code>, <code>offscreen</code>)</td><td>Recursos técnicos do navegador que permitem à extensão realizar tarefas em segundo plano, sem abrir janelas.</td></tr></tbody></table><p>Nenhuma dessas permissões envia dados ao desenvolvedor. Detalhes em <a href="./privacidade">Privacidade e dados</a>.</p><h2 id="_3-ativar-a-extensao" tabindex="-1">3. Ativar a extensão <a class="header-anchor" href="#_3-ativar-a-extensao" aria-label="Permalink to &quot;3. Ativar a extensão&quot;">​</a></h2><p>Logo depois da instalação, o eploc vem <strong>desativado</strong> e abre sozinho a página de configurações, na aba <strong>Sobre</strong>.</p><ol><li>Leia os termos de uso e isenção de responsabilidade.</li><li>Marque <strong>Li e aceito os termos de uso e isenção de responsabilidade acima</strong>.</li><li>Clique em <strong>Confirmar aceite</strong>. A extensão é ativada.</li></ol><p>Se você tentar ligar a extensão pelo popup antes de aceitar os termos, a página de configurações é aberta para o aceite. Quando os termos mudam, o aceite é pedido de novo.</p><h2 id="_4-primeira-configuracao" tabindex="-1">4. Primeira configuração <a class="header-anchor" href="#_4-primeira-configuracao" aria-label="Permalink to &quot;4. Primeira configuração&quot;">​</a></h2><ol><li>Abra um processo no eproc. As funcionalidades que vêm ligadas já aparecem.</li><li>Clique no ícone do eploc para ver, no <a href="./geral/popup">popup</a>, quais funcionalidades valem naquela página, com um interruptor para cada uma.</li><li>Para ajustar opções, abra a <a href="./geral/configuracoes">página de configurações</a> (botão <strong>Configurações</strong> do popup). As funcionalidades estão organizadas por sistema (eproc, RUPE, SEI, TJMG) e por tema.</li><li>Algumas funcionalidades vêm desligadas e valem a pena conhecer: <a href="./funcionalidades/eproc-alertas-inline">Alertas menos intrusivos</a>, <a href="./funcionalidades/eproc-auto-carregar-todos-eventos">Carregar todos os eventos automaticamente</a> e <a href="./funcionalidades/eproc-auto-manter-agendamento">Manter agendamento da minuta automaticamente</a>.</li><li>Use a busca das configurações para achar qualquer ajuste pelo nome. Basta começar a digitar.</li></ol><h2 id="_5-conectar-o-google-drive-opcional" tabindex="-1">5. Conectar o Google Drive (opcional) <a class="header-anchor" href="#_5-conectar-o-google-drive-opcional" aria-label="Permalink to &quot;5. Conectar o Google Drive (opcional)&quot;">​</a></h2><p>O backup no Google Drive guarda suas configurações e dados na sua própria conta Google, numa pasta oculta reservada ao eploc, e permite usá-los em outro computador.</p><ol><li>Nas configurações, abra a aba <strong>Ajustes gerais e Backup</strong>.</li><li>No card <strong>Backup no Google Drive</strong>, ligue <strong>Habilitar backup no Google Drive</strong>.</li><li>Na janela do Google, escolha sua conta. A tela de consentimento identifica o aplicativo como <strong>eploc</strong> e pede acesso só aos dados de configuração do próprio aplicativo no seu Drive (escopo <code>drive.appdata</code>). O eploc não vê nem altera seus outros arquivos.</li><li>Autorize. Se a conta já tiver backups do eploc, você pode revisá-los e restaurá-los na hora.</li><li>Para manter vários computadores em sincronia, ligue também <strong>Manter sincronizado automaticamente entre dispositivos</strong>.</li></ol><p>Passo a passo completo e limitações em <a href="./geral/backup-google-drive">Backup no Google Drive</a>.</p>',19)]))}const g=e(s,[["render",t]]);export{m as __pageData,g as default};
